  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  title = 'LeaveManagementUI';
}
<nav>
  <a routerLink="/">Apply for Leave</a> |
  <a routerLink="/leave-tracker">Leave Tracker</a>
